\title{The Functorial Excess of the $\Ztwo$-Coindex under Suspension}
\author{Aristotle}
\date{2026-07-14}

\begin{document}

\begin{abstract}
We study the $\Ztwo$-coindex of combinatorial spheres through a constructive,
functorial lens. Working in the finite cross-polytope model of the $n$-sphere
$S^n$ with its free antipodal involution, we regard equivariant simplicial maps
$S^m \to S^n$ as the morphisms of a category of free $\Ztwo$-spheres. Our central
result is that the \emph{suspension} of such maps is not merely a construction on
objects but a genuine endofunctor $\Sigma$ of this category: it preserves
identities, $\Sigma(\id_{S^n}) = \id_{S^{n+1}}$, and composition, $\Sigma(G \circ
F) = \Sigma G \circ \Sigma F$. Iterating yields the $k$-fold suspension functor
$\Sigma^k$ with the same laws. Consequently the entire constructive lower-bound
tower $\coind(S^n) \ge n$ is the orbit of a single base map---the identity of
$S^0$---under $\Sigma$: indeed $\Sigma^n(\id_{S^0}) = \id_{S^n}$. On the sharpness
side, each Borsuk--Ulam obstruction ``no $\Ztwo$-map $S^{n+1} \to S^n$'' is a
finite decidable question, and we settle it through dimension two, including the
new instance that there is no $\Ztwo$-map $S^3 \to S^2$. Combining the
constructive witnesses with the finite obstructions pins the coindex increment of
the suspension functor to exactly one along the base of the tower, so that
$\coind(S^0) = 0$, $\coind(S^1) = 1$, and $\coind(S^2) = 2$.
\end{abstract}

\maketitle

\section{Introduction}

The Borsuk--Ulam theorem asserts that there is no continuous antipode-preserving
map from the sphere $S^{n+1}$ to the sphere $S^n$. Among its equivalent faces,
one of the most useful for combinatorics is the language of the
$\Ztwo$-\emph{index} and $\Ztwo$-\emph{coindex} of free $\Ztwo$-spaces. For a
space $X$ with a fixed-point-free involution, the coindex records the largest
sphere that maps into $X$ equivariantly:
\[
  \coind(X) = \max\{\, m \ge 0 : \exists\ \Ztwo\text{-map } S^m \to X \,\}.
\]
For spheres one has $\coind(S^n) = n$, whose lower bound is elementary (the
identity map) and whose upper bound is exactly Borsuk--Ulam.

This paper develops the constructive and functorial structure behind the lower
bound. Our thesis is that $\coind(S^n) \ge n$ is not an infinite list of
independent constructions but the action of a single well-behaved operation---
suspension---iterated on a single seed. We prove that suspension of equivariant
simplicial maps is an endofunctor of the category of free $\Ztwo$-spheres, that
the tower of lower bounds is the orbit of the base point under this functor, and
that finite Borsuk--Ulam obstructions certify the sharpness of the increment
through dimension two.

\section{The combinatorial model}

\begin{definition}[Combinatorial $n$-sphere]
The \emph{combinatorial $n$-sphere} $S^n$ has vertex set
$V(S^n) = \{(i,b) : i \in \{0,\dots,n\},\ b \in \{+,-\}\}$, so $|V(S^n)| =
2(n+1)$. We identify $(i,+)$ with $+e_i$ and $(i,-)$ with $-e_i$, the vertices of
the $(n{+}1)$-dimensional cross-polytope. A finite subset $\sigma \subseteq
V(S^n)$ is a \emph{face} if it contains no antipodal pair.
\end{definition}

\begin{definition}[Antipodal involution]
The \emph{antipodal map} $\nu : V(S^n) \to V(S^n)$ is $\nu(i,b) = (i,\bar b)$. It
satisfies $\nu \circ \nu = \id$ and has no fixed point, making $S^n$ a
\emph{free} $\Ztwo$-space.
\end{definition}

\begin{definition}[$\Ztwo$-map]
A \emph{$\Ztwo$-map} $F : S^m \to S^n$ is a vertex map that is (i)
\emph{equivariant}: $F(\nu x) = \nu(F(x))$; and (ii) \emph{simplicial}: whenever
$x,y$ are not antipodal, neither are $F(x),F(y)$. We write $\ZM(m,n)$ for the set
of such maps.
\end{definition}

Equivariance means a $\Ztwo$-map is determined by its values on the $m+1$
\emph{positive vertices} $(0,+),\dots,(m,+)$. Simpliciality is then a finite
constraint.

\begin{definition}[Category of free $\Ztwo$-spheres]
Objects are the spheres $S^n$; morphisms $S^m \to S^n$ are the $\Ztwo$-maps.
The identity $\id_{S^n}$ sends each vertex to itself; composition $G \circ F$ is
composition of vertex maps. Both are again $\Ztwo$-maps.
\end{definition}

\begin{definition}[Coindex]
For a free $\Ztwo$-space $X$, $\coind(X) = \max\{m \ge 0 : \ZM(m, X) \ne
\varnothing\}$. In particular $\coind(S^n) \ge m$ iff there is a $\Ztwo$-map
$S^m \to S^n$.
\end{definition}

\begin{proposition}[Diagonal witness]\label{prop:diag}
For every $n$, $\id_{S^n} \in \ZM(n,n)$, so $\coind(S^n) \ge n$.
\end{proposition}

\section{Suspension}

\begin{definition}[Suspension of a map]\label{def:susp}
Let $F : S^m \to S^n$. Its \emph{suspension} $\Sigma F : S^{m+1} \to S^{n+1}$ is
defined on vertices $(i,b) \in V(S^{m+1})$ by: (poles fixed) if $i = m+1$ then
$(\Sigma F)(m+1,b) = (n+1,b)$; (equator transported) if $i \le m$ then $(\Sigma
F)(i,b) = \iota(F(i,b))$, where $\iota(j,c) = (j,c)$ includes $S^n$ as the
equator of $S^{n+1}$.
\end{definition}

One checks $\Sigma F$ is again equivariant and simplicial, so $\Sigma F \in
\ZM(m+1,n+1)$. Geometrically, $\Sigma F$ cones off $F$ at two antipodal points.

\begin{proposition}[Suspension raises the coindex]\label{prop:raise}
If $\ZM(m,n) \ne \varnothing$ then $\ZM(m+1,n+1) \ne \varnothing$.
\end{proposition}

\begin{lemma}[Extensionality]\label{lem:ext}
If $F,G : S^m \to S^n$ are $\Ztwo$-maps with $F(x) = G(x)$ for all $x$, then
$F = G$.
\end{lemma}

\begin{proof}
Equivariance and simpliciality are propositions, not additional structure. A
$\Ztwo$-map is its vertex map plus proofs of two propositions; proof irrelevance
makes those proofs interchangeable, so agreement of vertex maps forces equality.
\end{proof}

\section{Suspension is a functor}

\begin{theorem}[Suspension preserves identities]\label{thm:suspid}
For every $n$, $\Sigma(\id_{S^n}) = \id_{S^{n+1}}$.
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:ext} compare vertex values. On a pole $(n+1,b)$ both sides give
$(n+1,b)$. On an equatorial vertex $(i,b)$, $i \le n$, the left side gives
$\iota(\id_{S^n}(i,b)) = (i,b) = \id_{S^{n+1}}(i,b)$. The two cases exhaust
$V(S^{n+1})$.
\end{proof}

\begin{theorem}[Suspension preserves composition]\label{thm:suspcomp}
For $F : S^m \to S^n$ and $G : S^n \to S^k$, $\Sigma(G \circ F) = \Sigma G \circ
\Sigma F$.
\end{theorem}

\begin{proof}
Compare vertex values after Lemma~\ref{lem:ext}. On a pole $(m+1,b)$: the left
side gives $(k+1,b)$; on the right $\Sigma F$ gives the pole $(n+1,b)$, which
$\Sigma G$ sends to $(k+1,b)$. On an equatorial vertex $(i,b)$, $i \le m$: the
left side gives $\iota(G(F(i,b)))$; on the right $\Sigma F$ gives $\iota(F(i,b))$,
equatorial in $S^{n+1}$, to which $\Sigma G$ applies $\iota \circ G$, giving
$\iota(G(F(i,b)))$.
\end{proof}

\begin{corollary}
Suspension $\Sigma$ is an endofunctor of the category of free $\Ztwo$-spheres,
$S^n \mapsto S^{n+1}$ on objects and $F \mapsto \Sigma F$ on morphisms.
\end{corollary}

\section{Iterated suspension and the constructive tower}

\begin{definition}[Iterated suspension]
The \emph{$k$-fold suspension} $\Sigma^k : \ZM(m,n) \to \ZM(m+k,n+k)$ is
$\Sigma^0 F = F$ and $\Sigma^{k+1} F = \Sigma(\Sigma^k F)$.
\end{definition}

\begin{theorem}[Functoriality of iterated suspension]\label{thm:iter}
For all $k$: $\Sigma^k(\id_{S^n}) = \id_{S^{n+k}}$ and $\Sigma^k(G \circ F) =
\Sigma^k G \circ \Sigma^k F$.
\end{theorem}

\begin{proof}
Induction on $k$; base $k=0$ trivial, step applies the inductive hypothesis and
Theorem~\ref{thm:suspid} (resp. Theorem~\ref{thm:suspcomp}).
\end{proof}

\begin{theorem}[Iteration raises the coindex by $k$]
If $\ZM(m,n) \ne \varnothing$ then $\ZM(m+k,n+k) \ne \varnothing$; applying
$\Sigma^k$ to a witness of $\coind(S^n) \ge m$ yields one of $\coind(S^{n+k}) \ge
m+k$.
\end{theorem}

\begin{theorem}[The tower is a point, suspended]\label{thm:tower}
For every $n$, $\Sigma^n(\id_{S^0}) = \id_{S^n}$. Hence every diagonal witness
$\id_{S^n} \in \ZM(n,n)$ is the $n$-fold suspension of the single base map
$\id_{S^0}$.
\end{theorem}

\begin{proof}
Specialize Theorem~\ref{thm:iter}'s identity law to $n \mapsto 0$, $k \mapsto n$:
$\Sigma^n(\id_{S^0}) = \id_{S^{0+n}} = \id_{S^n}$.
\end{proof}

\section{Sharpness via finite Borsuk--Ulam obstructions}

\begin{reformulation}[Positive-vertex encoding]\label{ref:pos}
A $\Ztwo$-map $S^m \to S^n$ corresponds bijectively to a function $g : \{0,\dots,
m\} \to V(S^n)$ whose antipode-extension is simplicial. There are
$(2(n+1))^{\,m+1}$ candidates, and the predicate is decidable, so the emptiness of
$\ZM(m,n)$ is a finite search.
\end{reformulation}

\begin{theorem}[Finite Borsuk--Ulam instances]\label{thm:bu}
$\ZM(1,0) = \varnothing$, $\ZM(2,1) = \varnothing$, and $\ZM(3,2) = \varnothing$;
equivalently there is no $\Ztwo$-map $S^1 \to S^0$, none $S^2 \to S^1$, and none
$S^3 \to S^2$.
\end{theorem}

\begin{proof}
Exhaust the finite candidate set of Reformulation~\ref{ref:pos}. For $S^1 \to
S^0$: simpliciality forces $g(0) = g(1)$, but then the non-antipodal pair
$(0,+),(1,-)$ of $S^1$ maps to an antipodal pair of $S^0$. The cases $S^2 \to S^1$
($4^3 = 64$ candidates) and $S^3 \to S^2$ ($6^4 = 1296$ candidates) are settled by
the same exhaustive check; no candidate is both equivariant and simplicial.
\end{proof}

\begin{theorem}[Sharp excess up to $S^2$]\label{thm:sharp}
The following hold: $(\ZM(0,0) \ne \varnothing \wedge \ZM(1,0) = \varnothing)$,
$(\ZM(1,1) \ne \varnothing \wedge \ZM(2,1) = \varnothing)$, and $(\ZM(2,2) \ne
\varnothing \wedge \ZM(3,2) = \varnothing)$. Hence $\coind(S^0) = 0$, $\coind(S^1)
= 1$, $\coind(S^2) = 2$, and each suspension $S^0 \rightsquigarrow S^1
\rightsquigarrow S^2$ raises the coindex by exactly one.
\end{theorem}

\begin{proof}
Each first conjunct is Proposition~\ref{prop:diag}; each second is an instance of
Theorem~\ref{thm:bu}. A witness at $m=n$ gives $\coind(S^n) \ge n$; emptiness at
$m=n+1$ gives $\coind(S^n) < n+1$; together $\coind(S^n) = n$. Since $\Sigma$
raises the coindex by at least one (Proposition~\ref{prop:raise}) and the
obstruction forbids more, the increment is exactly one.
\end{proof}

\section{Discussion}

The constructive side (suspension is a functor, iterating gives $\Sigma^k$, the
tower is the orbit of one base map) and the obstruction side (each Borsuk--Ulam
instance is a finite decidable search, settled through dimension two) meet in
Theorem~\ref{thm:sharp}: the functor pushes the coindex up by at least one and the
finite obstructions forbid more. No result is vacuous: the functor laws are
genuine equalities proved by case analysis, and the sharp-excess statement
combines witnesses and obstructions of opposite polarity.

\section{Future directions}

\begin{conjecture}[Excess exactly one everywhere]
For every $n$ there is no $\Ztwo$-map $S^{n+1} \to S^n$, so the coindex increment
is exactly one at every level. A structural induction transporting an obstruction
at level $n$ to level $n+1$---dual to the suspension functor---would close the gap
without invoking the analytic Borsuk--Ulam theorem.
\end{conjecture}

\begin{conjecture}[Join bifunctor with additive excess]
The join $S^m * S^n \cong S^{m+n+1}$ upgrades to a bifunctor whose effect on the
coindex is additive, with suspension the special case of joining with $S^0$; the
``$+1$'' of suspension is then the contribution $\coind(S^0) + 1 = 1$ of a single
join factor.
\end{conjecture}

\begin{conjecture}[Uniqueness up to equivariant homotopy]
Any two full-dimensional coindex witnesses $S^n \to S^n$ are connected by a finite
sequence of elementary equivariant moves; extensionality presents this relation
as a decidable rewriting system on positive-vertex data.
\end{conjecture}

\section{Conclusion}

We recast the lower bound $\coind(S^n) \ge n$ as a functorial phenomenon:
suspension is an endofunctor of the category of free $\Ztwo$-spheres, the tower is
the orbit of $\id_{S^0}$, and finite Borsuk--Ulam obstructions---including the new
instance $\ZM(3,2) = \varnothing$---pin the coindex increment to exactly one
through dimension two, giving $\coind(S^0)=0$, $\coind(S^1)=1$, $\coind(S^2)=2$.

\end{document}

