"""Verify the functor laws of suspension by exhaustive enumeration.

For every Z2-map between low-dimensional combinatorial spheres, we check that
suspension preserves identities (Sigma(id) = id) and composition
(Sigma(h.g) = Sigma(h).Sigma(g)). A Z2-map S^m -> S^n is stored as the tuple of
images of its positive vertices; the value on a negative vertex is the antipode.
"""
from __future__ import annotations
from itertools import product
from typing import List, Tuple

Vertex = Tuple[int, bool]
PosMap = Tuple[Vertex, ...]

def vertices(n: int) -> List[Vertex]:
    return [(i, b) for i in range(n + 1) for b in (False, True)]

def antipode(v: Vertex) -> Vertex:
    i, b = v
    return (i, not b)

def apply_map(g: PosMap, v: Vertex) -> Vertex:
    i, b = v
    return g[i] if not b else antipode(g[i])

def is_simplicial(g: PosMap, m: int, n: int) -> bool:
    vs = vertices(m)
    for u in vs:
        for w in vs:
            if u == w or u == antipode(w):
                continue
            if apply_map(g, u) == antipode(apply_map(g, w)):
                return False
    return True

def all_z2maps(m: int, n: int) -> List[PosMap]:
    return [g for g in product(vertices(n), repeat=m + 1) if is_simplicial(g, m, n)]

def identity_map(n: int) -> PosMap:
    return tuple((i, False) for i in range(n + 1))

def suspend(g: PosMap, n: int) -> PosMap:
    return tuple(list(g) + [(n + 1, False)])

def compose(h: PosMap, g: PosMap) -> PosMap:
    return tuple(apply_map(h, g[i]) for i in range(len(g)))

def main() -> None:
    for n in range(4):
        assert suspend(identity_map(n), n) == identity_map(n + 1)
    print("identity law Sigma(id_S^n) = id_S^{n+1} verified for n = 0..3")
    checked = 0
    for g in all_z2maps(1, 1):
        for h in all_z2maps(1, 1):
            assert suspend(compose(h, g), 1) == compose(suspend(h, 1), suspend(g, 1))
            checked += 1
    print(f"composition law verified on {checked} pairs of Z2-maps S^1->S^1->S^1")

if __name__ == "__main__":
    main()

"""Exhaustive finite Borsuk-Ulam search over combinatorial spheres.

For fixed m, n the existence of an equivariant simplicial map S^m -> S^n is a
finite decidable question: a candidate is a choice of image in S^n for each of the
m+1 positive vertices of S^m, and simpliciality is checked on all vertex pairs.
This script confirms the obstructions coind(S^n) < n+1 for n = 0, 1, 2 by finding
zero maps S^1->S^0, S^2->S^1, and S^3->S^2, and prints the coindex table.
"""
from __future__ import annotations
from itertools import product
from typing import List, Tuple

Vertex = Tuple[int, bool]
PosMap = Tuple[Vertex, ...]

def vertices(n: int) -> List[Vertex]:
    return [(i, b) for i in range(n + 1) for b in (False, True)]

def antipode(v: Vertex) -> Vertex:
    i, b = v
    return (i, not b)

def apply_map(g: PosMap, v: Vertex) -> Vertex:
    i, b = v
    return g[i] if not b else antipode(g[i])

def is_simplicial(g: PosMap, m: int, n: int) -> bool:
    vs = vertices(m)
    for u in vs:
        for w in vs:
            if u == w or u == antipode(w):
                continue
            if apply_map(g, u) == antipode(apply_map(g, w)):
                return False
    return True

def count_maps(m: int, n: int) -> int:
    return sum(1 for g in product(vertices(n), repeat=m + 1) if is_simplicial(g, m, n))

def coindex(n: int, search_up_to: int = 6) -> int:
    best = -1
    for m in range(search_up_to + 1):
        if count_maps(m, n) > 0:
            best = m
    return best

def main() -> None:
    print("Borsuk-Ulam obstructions:")
    for (m, n) in [(1, 0), (2, 1), (3, 2)]:
        c = count_maps(m, n)
        print(f"  #Z2maps(S^{m} -> S^{n}) = {c}  (empty: {c == 0})")
    print("coindex table:")
    for n in range(3):
        print(f"  coind(S^{n}) = {coindex(n)}")

if __name__ == "__main__":
    main()

