    return tuple(list(g) + [(n + 1, False)])

def coindex_witness(n: int) -> PosMap:
    """Construct the full-dimensional coindex witness S^n -> S^n by iterating
    suspension on the base map id_{S^0}. The result equals id_{S^n}, certifying
    coind(S^n) >= n purely functorially."""
    g, dim = identity_map(0), 0
    for _ in range(n):
        g = suspend(g, dim)
        dim += 1
    return g

