            if u == w or u == antipode(w):
                continue
            if apply_map(g, u) == antipode(apply_map(g, w)):
                return False
    return True

def count(m, n):
    return sum(1 for g in product(vertices(n), repeat=m + 1) if is_simplicial(g, m))

